import json
import os
import re
import unicodedata
from datetime import datetime, timezone
from typing import Any

from exa_py import Exa


query = """herecomesquery"""
summary_query = """herecomessummaryquery"""
exclude_domains_raw = """herecomesexcludedomains"""
include_domains_raw = """herecomesincludedomains"""
additional_queries_raw = """herecomesadditionalqueries"""
system_prompt = """herecomessystemprompt"""
start_published_date = """herecomesstartpublisheddate"""
end_published_date = """herecomesendpublisheddate"""
search_type = """herecomessearchtype"""
category = """herecomescategory"""
num_results_raw = """herecomesnumresults"""
max_characters_raw = """herecomesmaxcharacters"""
max_age_hours_raw = """herecomesmaxagehours"""
livecrawl_timeout_raw = """herecomeslivecrawltimeout"""
stream_raw = """herecomesstream"""
user_location = """herecomesuserlocation"""
compliance = """herecomescompliance"""
output_schema_raw = """herecomesoutputschema"""
summary_schema_raw = """herecomessummaryschema"""


exa = Exa(api_key=os.environ.get("EXA_API_KEY"))


def parse_optional_json(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, (dict, list, bool, int, float)):
        return value
    text = str(value).strip()
    if not text:
        return None
    lower = text.lower()
    if lower in {"none", "null"}:
        return None
    try:
        return json.loads(text)
    except Exception:
        return None


def parse_optional_int(value: Any) -> int | None:
    if value is None:
        return None
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    text = str(value).strip()
    if not text:
        return None
    lower = text.lower()
    if lower in {"none", "null"}:
        return None
    return int(text)


def parse_optional_bool(value: Any) -> bool | None:
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if not text or text in {"none", "null"}:
        return None
    if text in {"true", "1", "yes", "y", "on"}:
        return True
    if text in {"false", "0", "no", "n", "off"}:
        return False
    raise ValueError(f"Invalid boolean value: {value}")


def parse_optional_string(value: Any) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text or text.lower() in {"none", "null"}:
        return None
    return text


def normalize_domain(raw_domain: Any) -> str:
    domain = str(raw_domain).strip().strip("\"'{}<>").strip()
    domain = re.sub(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", "", domain)
    domain = re.split(r"[/?#]", domain, maxsplit=1)[0]
    domain = domain.rsplit("@", 1)[-1]
    domain = re.sub(r":\d+$", "", domain)
    domain = domain.strip(".").lower()
    return domain


def parse_domain_list(raw_value: Any) -> list[str]:
    if raw_value is None:
        return []
    if isinstance(raw_value, str):
        text = raw_value.strip()
        if not text or text.lower() in {"none", "null"}:
            return []
        parsed_json = parse_optional_json(text)
        if isinstance(parsed_json, list):
            entries = parsed_json
        else:
            entries = re.split(r"[,\s;]+", text)
    elif isinstance(raw_value, (list, tuple, set)):
        entries = list(raw_value)
    else:
        entries = [raw_value]
    domains: list[str] = []
    for entry in entries:
        normalized = normalize_domain(entry)
        if normalized and normalized not in domains:
            domains.append(normalized)
    return domains


def parse_string_list(raw_value: Any) -> list[str]:
    if raw_value is None:
        return []
    if isinstance(raw_value, str):
        text = raw_value.strip()
        if not text or text.lower() in {"none", "null"}:
            return []
        parsed_json = parse_optional_json(text)
        if isinstance(parsed_json, list):
            values = parsed_json
        else:
            values = [item.strip() for item in re.split(r"[;\n]+", text) if item.strip()]
    elif isinstance(raw_value, (list, tuple, set)):
        values = list(raw_value)
    else:
        values = [raw_value]
    result: list[str] = []
    for value in values:
        item = str(value).strip()
        if item and item not in result:
            result.append(item)
    return result


def compact_dict(data: dict[str, Any]) -> dict[str, Any]:
    return {key: value for key, value in data.items() if value is not None}


def sanitize_filename(value: str, fallback: str = "query", limit: int = 100) -> str:
    normalized = unicodedata.normalize("NFKD", value)
    ascii_value = normalized.encode("ascii", "ignore").decode("ascii")
    cleaned = re.sub(r"[^a-zA-Z0-9]+", "_", ascii_value).strip("_").lower()
    cleaned = cleaned[:limit].rstrip("_")
    return cleaned or fallback


include_domains = parse_domain_list(include_domains_raw)
exclude_domains = parse_domain_list(exclude_domains_raw)
additional_queries = parse_string_list(additional_queries_raw)
parsed_output_schema = parse_optional_json(output_schema_raw)
parsed_summary_schema = parse_optional_json(summary_schema_raw)
parsed_num_results = parse_optional_int(num_results_raw)
parsed_max_characters = parse_optional_int(max_characters_raw)
parsed_max_age_hours = parse_optional_int(max_age_hours_raw)
parsed_livecrawl_timeout = parse_optional_int(livecrawl_timeout_raw)
parsed_stream = parse_optional_bool(stream_raw)
parsed_query = parse_optional_string(query)
parsed_summary_query = parse_optional_string(summary_query)
parsed_system_prompt = parse_optional_string(system_prompt)
parsed_start_published_date = parse_optional_string(start_published_date)
parsed_end_published_date = parse_optional_string(end_published_date)
parsed_search_type = parse_optional_string(search_type) or "auto"
parsed_category = parse_optional_string(category)
parsed_user_location = parse_optional_string(user_location)
parsed_compliance = parse_optional_string(compliance)

if not parsed_query:
    raise ValueError("query must be a non-empty string")

valid_search_types = {"auto", "fast", "instant", "deep-lite", "deep", "deep-reasoning"}
if parsed_search_type not in valid_search_types:
    raise ValueError(f"Invalid search type: {parsed_search_type}")

if parsed_num_results is not None and not (1 <= parsed_num_results <= 100):
    raise ValueError("numResults must be between 1 and 100")

if parsed_max_characters is not None and not (1 <= parsed_max_characters <= 1_000_000):
    raise ValueError("contents.text.maxCharacters must be between 1 and 1000000")

if parsed_max_age_hours is not None and not (-1 <= parsed_max_age_hours <= 720):
    raise ValueError("contents.maxAgeHours must be between -1 and 720")

if parsed_livecrawl_timeout is not None and not (1 <= parsed_livecrawl_timeout <= 90000):
    raise ValueError("contents.livecrawlTimeout must be between 1 and 90000")

if parsed_category is not None:
    valid_categories = {"company", "people", "research paper", "news", "personal site", "financial report", "publication"}
    if parsed_category not in valid_categories:
        raise ValueError(f"Invalid category: {parsed_category}")

if parsed_category in {"company", "people"}:
    if exclude_domains:
        raise ValueError("excludeDomains is not supported for category 'company' or 'people'")
    if parsed_start_published_date is not None or parsed_end_published_date is not None:
        raise ValueError("startPublishedDate and endPublishedDate are not supported for category 'company' or 'people'")

if additional_queries and parsed_search_type not in {"deep-lite", "deep", "deep-reasoning"}:
    raise ValueError("additionalQueries can only be used with deep-lite, deep, or deep-reasoning search types")

if parsed_stream and parsed_output_schema is None:
    raise ValueError("stream=true requires outputSchema")

contents: dict[str, Any] = {}

if parsed_max_characters is not None:
    contents["text"] = {"max_characters": parsed_max_characters}

summary_payload: dict[str, Any] = {}
if parsed_summary_query is not None:
    summary_payload["query"] = parsed_summary_query
if isinstance(parsed_summary_schema, dict):
    summary_payload["schema"] = parsed_summary_schema
if summary_payload:
    contents["summary"] = summary_payload

if parsed_max_age_hours is not None:
    contents["max_age_hours"] = parsed_max_age_hours

if parsed_livecrawl_timeout is not None:
    contents["livecrawl_timeout"] = parsed_livecrawl_timeout

search_kwargs = compact_dict(
    {
        "query": parsed_query,
        "type": parsed_search_type,
        "num_results": parsed_num_results if parsed_num_results is not None else 100,
        "category": parsed_category,
        "include_domains": include_domains or None,
        "exclude_domains": exclude_domains or None,
        "start_published_date": parsed_start_published_date,
        "end_published_date": parsed_end_published_date,
        "additional_queries": additional_queries or None,
        "system_prompt": parsed_system_prompt,
        "output_schema": parsed_output_schema if isinstance(parsed_output_schema, dict) else None,
        "stream": parsed_stream if parsed_stream is not None else None,
        "user_location": parsed_user_location,
        "compliance": parsed_compliance,
        "contents": contents or None,
    }
)

result = exa.search(**search_kwargs)

payload: dict[str, Any] = {
    "request_timestamp_utc": datetime.now(timezone.utc).isoformat(),
    "request": {
        "query": parsed_query,
        "summary_query": parsed_summary_query,
        "summary_schema": parsed_summary_schema,
        "include_domains": include_domains,
        "exclude_domains": exclude_domains,
        "additional_queries": additional_queries,
        "type": parsed_search_type,
        "category": parsed_category,
        "num_results": search_kwargs["num_results"],
        "start_published_date": parsed_start_published_date,
        "end_published_date": parsed_end_published_date,
        "system_prompt": parsed_system_prompt,
        "output_schema": parsed_output_schema,
        "stream": parsed_stream,
        "user_location": parsed_user_location,
        "compliance": parsed_compliance,
        "contents": contents,
    },
    "response": {
        "request_id": getattr(result, "request_id", None),
        "resolved_search_type": getattr(result, "resolved_search_type", None),
        "search_time": getattr(result, "search_time", None),
        "cost_dollars": getattr(result, "cost_dollars", None),
        "output": None,
        "results": [],
    },
}

result_output = getattr(result, "output", None)
if result_output is not None:
    payload["response"]["output"] = {
        "content": getattr(result_output, "content", None),
        "grounding": getattr(result_output, "grounding", None),
    }

for item in getattr(result, "results", []) or []:
    payload["response"]["results"].append(
        {
            "title": getattr(item, "title", None),
            "url": getattr(item, "url", None),
            "published_date": getattr(item, "published_date", None),
            "author": getattr(item, "author", None),
            "text": getattr(item, "text", None),
            "summary": getattr(item, "summary", None),
            "highlights": getattr(item, "highlights", None),
            "subpages": getattr(item, "subpages", None),
            "extras": getattr(item, "extras", None),
        }
    )

filename_query = sanitize_filename(parsed_query)
timestamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S_%f")
output_filename = f"{filename_query}_{timestamp}.json"

with open(output_filename, "w", encoding="utf-8") as json_file:
    json.dump(payload, json_file, ensure_ascii=False, indent=2)

print(output_filename)
